// Uploads the built artifact to the release bucket.
//
// This uses the S3 PutObject API directly so the release process does not
// require an installed cloud SDK. Authentication is supplied by the standard
// AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, and (when applicable)
// AWS_SESSION_TOKEN environment variables.
const crypto = require("crypto");
const fs = require("fs");

const BUCKET = "releases-eu-prod";
const VERSION = require("./version.json").version;
const REGION = process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION;

function objectName(version) {
  return `app-${version}.js`;
}

function sha256(value) {
  return crypto.createHash("sha256").update(value).digest("hex");
}

function hmac(key, value) {
  return crypto.createHmac("sha256", key).update(value).digest();
}

function awsDate(now) {
  return now.toISOString().replace(/[:-]|\.\d{3}/g, "");
}

function signingKey(secret, shortDate, region) {
  const dateKey = hmac(`AWS4${secret}`, shortDate);
  const regionKey = hmac(dateKey, region);
  const serviceKey = hmac(regionKey, "s3");
  return hmac(serviceKey, "aws4_request");
}

async function putObject({ body, name, accessKeyId, secretAccessKey, sessionToken }) {
  const now = new Date();
  const timestamp = awsDate(now);
  const date = timestamp.slice(0, 8);
  const host = `${BUCKET}.s3.${REGION}.amazonaws.com`;
  const path = `/${encodeURIComponent(name)}`;
  const payloadHash = sha256(body);
  const headers = {
    host,
    "x-amz-content-sha256": payloadHash,
    "x-amz-date": timestamp,
  };
  if (sessionToken) headers["x-amz-security-token"] = sessionToken;

  const canonicalHeaders = Object.entries(headers)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([key, value]) => `${key}:${value}\n`)
    .join("");
  const signedHeaders = Object.keys(headers).sort().join(";");
  const canonicalRequest = [
    "PUT",
    path,
    "",
    canonicalHeaders,
    signedHeaders,
    payloadHash,
  ].join("\n");
  const credentialScope = `${date}/${REGION}/s3/aws4_request`;
  const stringToSign = [
    "AWS4-HMAC-SHA256",
    timestamp,
    credentialScope,
    sha256(canonicalRequest),
  ].join("\n");
  const signature = crypto
    .createHmac("sha256", signingKey(secretAccessKey, date, REGION))
    .update(stringToSign)
    .digest("hex");

  const response = await fetch(`https://${host}${path}`, {
    method: "PUT",
    headers: {
      ...headers,
      Authorization:
        "AWS4-HMAC-SHA256 " +
        `Credential=${accessKeyId}/${credentialScope}, ` +
        `SignedHeaders=${signedHeaders}, Signature=${signature}`,
    },
    body,
  });
  if (!response.ok) {
    throw new Error(
      `S3 PUT ${BUCKET}/${name} failed (${response.status}): ${await response.text()}`,
    );
  }
}

async function main() {
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;
  if (!REGION) {
    throw new Error("AWS_REGION (or AWS_DEFAULT_REGION) must be set");
  }
  if (!accessKeyId || !secretAccessKey) {
    throw new Error(
      "AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY must be set to upload the release artifact",
    );
  }

  const body = fs.readFileSync("dist/app.js");
  const name = objectName(VERSION);
  await putObject({
    body,
    name,
    accessKeyId,
    secretAccessKey,
    sessionToken: process.env.AWS_SESSION_TOKEN,
  });
  console.log(`uploaded s3://${BUCKET}/${name} (${body.length} bytes)`);
}

main().catch((error) => {
  console.error(error.message);
  process.exitCode = 1;
});
